const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, terminal: false });
let lines = [];
rl.on('line', (line) => { lines.push(line.trim()); });
rl.on('close', () => {
    const [HPY, ATKY, DEFY] = lines[0].split(' ').map(Number);
    const [HPM, ATKM, DEFM] = lines[1].split(' ').map(Number);
    const [h, a, d] = lines[2].split(' ').map(Number);

    let minCost = Infinity;

    for (let dAtk = 0; dAtk <= 200; dAtk++) {
        const totalAtk = ATKY + dAtk;
        const dmgToMonster = totalAtk - DEFM;
        if (dmgToMonster <= 0) continue; // can't damage monster

        const turns = Math.ceil(HPM / dmgToMonster);

        for (let dDef = 0; dDef <= 200; dDef++) {
            const totalDef = DEFY + dDef;
            const dmgToYang = Math.max(0, ATKM - totalDef);

            let hpNeeded;
            if (dmgToYang === 0) {
                hpNeeded = 1; // just need to survive, 1 HP is enough
            } else {
                hpNeeded = dmgToYang * (turns - 1) + 1;
            }

            const extraHP = Math.max(0, hpNeeded - HPY);

            const cost = extraHP * h + dAtk * a + dDef * d;

            if (cost < minCost) {
                minCost = cost;
            }
        }
    }

    console.log(minCost);
});
